async function initializeClone(env2) {
  const database = env2.DB;
  if (await database.prepare("SELECT key FROM site_config WHERE key=?").bind("clone-initialized-v1").first()) return;
  const statements = [...clone_config_default, { key: "settings", value: JSON.stringify(clone_snapshot_default.settings) }].map((row) => database.prepare("INSERT OR IGNORE INTO site_config (key,value) VALUES (?,?)").bind(row.key, row.value));
  for (const source2 of clone_snapshot_default.sources) {
    statements.push(database.prepare("INSERT OR IGNORE INTO feed_cache (key,payload,attempted_at,succeeded_at,error) VALUES (?,?,?,?,NULL)").bind("news:" + source2.id, JSON.stringify(clone_snapshot_default.stories.filter((s) => s.sourceId === source2.id)), source2.attemptedAt, source2.succeededAt));
  }
  for (const quote of clone_snapshot_default.quotes) {
    statements.push(database.prepare("INSERT OR IGNORE INTO feed_cache (key,payload,attempted_at,succeeded_at,error) VALUES (?,?,?,?,NULL)").bind("market:" + quote.id, JSON.stringify([quote]), clone_snapshot_default.checkedAt, clone_snapshot_default.checkedAt));
  }
  statements.push(database.prepare("INSERT OR IGNORE INTO site_config (key,value) VALUES (?,?)").bind("clone-initialized-v1", "2026-10-09"));
  await database.batch(statements);
}

